        "physical_requirements": "Moderate physical condition required. The main challenge is the 250-step staircase to the crater rim. Suitable for most fitness levels with proper pacing.",
        "cultural_context": "Mount Bromo is sacred to the Tenggerese Hindus, who believe it was created when a Hindu god cut off the top of Mount Semeru to place it where Bromo now stands. The Tenggerese are the only Hindu community in predominantly Muslim East Java, maintaining ancient Javanese Hindu traditions unchanged for centuries. Their connection to the volcano is central to their identity and spiritual practices. Bromo represents the element of Earth in Javanese cosmology - symbolizing fertility, endurance, and the bridge between divine and human.",
        "local_tribes": [
            "Tenggerese"
        ],
        "rituals_festivals": [
            {
                "name": "Yadnya Kasada Festival",
                "month": "Kasada (12th month of Tengger calendar)",
                "description": "Annual offering ceremony where Tenggerese throw vegetables, livestock and money into the crater",
                "significance": "Honoring the mountain gods and ancestors, seeking protection and blessings"
            },
            {
                "name": "Karo Festival",
                "month": "Karo (Tengger New Year)",
                "description": "New Year celebrations with prayers, traditional performances, and family gatherings",
                "significance": "Celebrating new beginnings and maintaining cultural traditions"
            },
            {
                "name": "Unan-Unan Ceremony",
                "month": "Every 5 years",
                "description": "Major purification ceremony for the entire Tengger community",
                "significance": "Cleansing and renewal of the community and its relationship with the mountains"
            }
        ],
        "tips_for_visitors": "Depart around 3: 00 AM for sunrise viewing, wear multiple warm layers as temperatures drop to 5°C, bring camera for spectacular photos, consider horse ride across sand sea for authentic experience, respect temple and ceremonial areas, check weather forecast before visit",
