        "code": "TSE-001",
        "name": "Tumpak Sewu Waterfall",
        "category": "waterfall",
        "region": "Lumajang–Malang Border",
        "province": "East Java",
        "country": "Indonesia",
        "latitude": "-8.227",
        "longitude": "112.915",
        "altitude": 500,
        "area_hectares": "300",
        "terrain": "Volcanic canyon with steep cliffs, rocky paths, bamboo ladders, rope sections, and slippery surfaces",
        "best_time_to_visit": "May–July",
        "difficulty_level": "hard",
        "duration": "2–3 hours",
        "physical_demand": 4,
        "cultural_depth": 3,
        "photo_potential": 5,
        "weather_by_season": "Dry season (May-Oct): Best conditions with minimal rain, clear skies. Wet season (Nov-Apr): Heavy rainfall increases water flow and flash flood risk.",
        "rainfall_intensity": "High during wet season (300-600mm/month), Moderate during dry season (50-200mm/month)",
        "temperature_range": "18-25°C in canyon, 22-30°C outside",
        "trail_details": "Panoramic viewpoint accessible by short walk, then 45-60 minute descent to waterfall base using bamboo ladders, ropes, and rocky paths. Total distance: 1.5km round trip with 150m elevation change.",
        "required_gear": [
            "trekking_shoes",
            "gloves",
            "waterproof_bag",
            "dry_clothes",
            "water_bottle",
            "headlamp"
        ],
        "summary": "A multi-stream semicircular waterfall formed by Mount Semeru's volcanic erosion, known for its canyon trail and panoramic viewpoint with Semeru backdrop.",
        "description": "Tumpak Sewu, which translates to 'A Thousand Waterfalls' in Javanese, is one of Indonesia's most spectacular waterfall formations. Located on the border between Lumajang and Malang regencies, this horseshoe-shaped waterfall cascades down a volcanic cliff face in hundreds of individual streams, creating a breathtaking natural curtain of water.\r\n\r\nThe waterfall is fed by the Glidik River, which originates from the slopes of Mount Semeru, Java's highest and most active volcano. The panoramic viewpoint offers a stunning perspective with Semeru often visible in the background, especially during sunrise. The descent to the waterfall base involves navigating bamboo ladders, ropes, and rocky paths, making it an adventurous experience.\r\n\r\nLocals refer to Tumpak Sewu as 'Semeru's Breath,' representing the continuous flow of life from the volcano to the earth below.",
        "highlight": "Thousand-stream waterfall curtain with Mount Semeru backdrop",
        "main_attractions": [
            {
                "title": "Panoramic Sunrise Viewpoint",
                "description": "Spectacular sunrise over the waterfall with Mount Semeru backdrop"
            },
            {
                "title": "Canyon Descent Adventure",
                "description": "Exciting descent using ropes and bamboo ladders to the waterfall base"
            },
            {
                "title": "Thousand Water Streams",
                "description": "Witness hundreds of individual water streams forming a natural curtain"
            },
            {
                "title": "Goa Tetes Cave Connection",
                "description": "Explore the nearby cave system connected to the waterfall"
            }
        ],
        "key_highlights": [
            {
                "title": "Indonesia's Most Photogenic Waterfall",
                "description": "Stunning horseshoe-shaped curtain of water with volcanic backdrop"
            },
            {
                "title": "Adventure Canyon Descent",
                "description": "Thrilling descent using ropes and ladders for an up-close experience"
            },
            {
                "title": "Mount Semeru Backdrop",
                "description": "Unique photography opportunity with Java's highest volcano in background"
            },
            {
                "title": "Unique Geological Formation",
                "description": "Volcanic erosion created this spectacular multi-stream waterfall"
            }
        ],
        "permit_required": true,
