        "physical_requirements": "Excellent physical condition required. Must be comfortable with heights, steep descents, and using ropes. Not recommended for people with mobility issues, fear of heights, or heart conditions.",
        "cultural_context": "Tumpak Sewu holds deep significance for the local communities who view the waterfall as 'Semeru's Breath' - the physical manifestation of the volcano's life force flowing to the earth. The continuous flow of water symbolizes renewal, humility, and the natural cycle of life. While less explicitly ritualized than other sites, the waterfall represents the power and generosity of nature in local cosmology. The name itself, 'A Thousand Waterfalls,' reflects the Javanese appreciation for nature's abundance and complexity.",
