        "seo_title": "Tumpak Sewu Waterfall - Java's Most Spectacular Water Curtain",
        "seo_description": "Experience Tumpak Sewu, the thousand-stream waterfall with Mount Semeru backdrop. Complete adventure guide to the canyon descent and photography. JVTO tours include expert guides and safety equipment.",
