            "tripRef": "/trips/trip-package-BALI-4D3N-001.json",
            "description": "Experience the best of East Java on this 4-day adventure, starting with a scenic transfer from <span class=\"fw-600\">Bali</span> to <span class=\"fw-600\">Banyuwangi</span>. After a relaxing journey, check into your hotel and unwind. On the second day, begin your adventure at <span class=\"fw-600\">Ijen Crater</span>, where you\u2019ll trek to the rim and witness the stunning turquoise sulfuric crater lake and meet the brave sulfur miners. Afterward, enjoy a break with Malabar coffee, followed by a delicious lunch in Bondowoso. In the evening, head to <span class=\"fw-600\">Papuma Beach</span> to watch a breathtaking sunset over the sea.<br><br>\r\n\r\nOn the third day, explore the magnificent <span class=\"fw-600\">Tumpak Sewu Waterfall</span>, known for its curtain-like water flow, surrounded by smaller cascades. Trek through the canyon and enjoy a natural water spa before continuing to the Bromo area. Check into your hotel and relax in preparation for the sunrise adventure the next morning. On the final day, experience the beauty of <span class=\"fw-600\">Mount Bromo</span> at sunrise, with views of <span class=\"fw-600\">Mount Batok</span>, <span class=\"fw-600\">Mount Bromo</span>, and <span class=\"fw-600\">Gunung Semeru</span>. Afterward, explore the crater rim and enjoy a thrilling 4WD ride across the sand sea before heading back to <span class=\"fw-600\">Surabaya</span>.<br><br>\r\n\r\nThis tour includes comfortable accommodations, private transportation, and expert <span class=\"fw-600\">English-speaking guides</span>. You\u2019ll enjoy all permits, entry fees, meals, and mineral water, ensuring a seamless and unforgettable experience.",
