            "tripRef": "/trips/trip-package-BALI-5D4N-001.json",
            "description": "Your journey begins with a scenic ferry crossing from Bali to Banyuwangi, where you'll spend the night before setting out for an unforgettable trek to the stunning <span class=\"fw-600\">Ijen Crater</span>. Witness the turquoise crater lake, meet the courageous sulfur miners, and enjoy the serene sunrise over one of Indonesia's most iconic volcanoes. Afterward, relax with a coffee break and head to <span class=\"fw-600\">Papuma Beach</span> to catch a breathtaking sunset. \r\n<br><br>\r\nNext, prepare for an early adventure to <span class=\"fw-600\">Tumpak Sewu Waterfall</span>, often called Java's grandest waterfall for its spectacular curtain-like cascades. Trek through the canyon to fully experience its beauty before continuing to the <span class=\"fw-600\">Bromo</span> area for a night of rest. The following day, enjoy a magical stargazing experience and witness the sunrise over Mount Bromo\u2019s dramatic landscape. Explore the <span class=\"fw-600\">Sand Sea</span>, visit the <span class=\"fw-600\">Poten Temple</span>, and trek up to the crater rim for panoramic views.\r\n<br><br>\r\nYour adventure concludes with a scenic drive to <span class=\"fw-600\">Surabaya</span>, where you\u2019ll enjoy a comfortable stay before departing from Juanda International Airport. This East Java expedition is designed to showcase the region's most stunning landscapes, offering an unforgettable experience from start to finish.",
