            "tripRef": "/trips/trip-package-SUB-1D1N-001.json",
            "description": "Experience the magic of Mount Bromo on this unforgettable one-day sunrise tour. Your adventure begins with an early pickup from your hotel in Surabaya, followed by a scenic 2-hour drive to the base of Mount Bromo at Cemoro Lawang. Once there, switch to a vintage 4WD Jeep for a thrilling ride up to Kingkong Hill, where you\u2019ll wait for the spectacular sunrise over the volcanic landscape. Enjoy panoramic views of Mount Bromo, Mount Batok, and the towering Mount Semeru. Don\u2019t forget to bring warm clothes, as the early morning can be quite chilly. After the sunrise, embark on a journey to the Bromo Crater, where you\u2019ll experience the otherworldly sight of sulfurous smoke rising from the depths. You can either walk or take a pony ride through the vast Sand Sea to reach the crater\u2019s edge. Next, visit the Whispering Sand, a serene and mysterious location that adds to the ethereal atmosphere of Mount Bromo. Afterward, enjoy a well-deserved breakfast at a local restaurant before heading back to Surabaya, where the tour concludes around noon. This unforgettable day offers the perfect blend of adventure and natural beauty.",
