            "tripRef": "/trips/trip-package-SUB-6D5N-001.json",
            "description": "Experience the <span class=\"fw-600\">Ultimate East Java Journey</span>, a 6-day exploration that combines breathtaking landscapes, thrilling adventures, and cultural discoveries. Start your trip with a scenic drive from <span class=\"fw-600\">Surabaya</span> to Bondowoso, where you\u2019ll rest before embarking on a midnight adventure to <span class=\"fw-600\">Ijen Crater</span>. Witness the stunning <span class=\"fw-600\">Blue Fire</span> and vibrant crater lake at sunrise, followed by a visit to <span class=\"fw-600\">Papuma Beach</span> to enjoy a tranquil sunset. Afterward, explore the famous <span class=\"fw-600\">Tumpak Sewu Waterfall</span>, then continue to the Bromo area for the night. <br><br>\r\n\r\nThe journey continues with an early morning stargazing experience at <span class=\"fw-600\">Mount Bromo</span>, where you\u2019ll witness the sunrise over a landscape of volcanic peaks. A thrilling ride through the Sand Sea takes you to the <span class=\"fw-600\">Bromo Crater</span>, before heading to <span class=\"fw-600\">Malang</span> for a relaxing evening. On Day 5, explore <span class=\"fw-600\">Batu City</span>, known for its scenic views, colorful <span class=\"fw-600\">Jodipan Village</span>, and apple harvesting. Finally, return to <span class=\"fw-600\">Surabaya</span>, where the adventure concludes with a transfer to the airport. <br><br>\r\n\r\nThroughout this tour, you\u2019ll experience the natural beauty and rich culture of East Java, with opportunities for adventure, relaxation, and learning. From the surreal landscapes of volcanic craters to the picturesque beaches and waterfalls, each day offers a new and exciting chapter in this unforgettable journey. Whether you\u2019re trekking to the top of <span class=\"fw-600\">Ijen</span> or wandering through the charming streets of <span class=\"fw-600\">Malang</span>, this trip will leave you with lasting memories and a deeper appreciation of East Java\u2019s wonders.",
