            "tripRef": "/trips/trip-package-BALI-3D2N-001.json",
            "description": "Explore the stunning volcanoes of East Java on this 3-day adventure from Bali. Begin your journey with a scenic transfer from Bali to the Bromo area, where you'll enjoy a relaxing evening at your hotel in Cemoro Lawang. The next morning, get ready for a thrilling sunrise experience at Mount Bromo, where you'll witness the majestic views of Mount Batok, Mount Bromo, and Gunung Semeru, Indonesia's highest volcano. After the sunrise, take an exciting 4WD ride across the volcanic sand sea, and then choose between hiking or riding a pony to the crater rim for an up-close look at the active volcano. In the afternoon, continue your journey to Bondowoso City, where you'll spend the night and prepare for the next adventure. On the third day, experience the magical blue fire of Ijen Crater during a sunrise trek. Hike up to the crater rim, where you'll be amazed by the turquoise sulfuric lake and the hard-working sulfur miners who brave dangerous conditions to extract sulfur. After exploring the crater, enjoy a break with a cup of Arabica coffee before making your way back to Ketapang Harbour for the ferry ride back to Bali. This tour includes comfortable accommodations, private transportation, and experienced English-speaking guides to ensure a smooth and unforgettable experience. Enjoy all permits, entry fees, meals, and mineral water during your journey, making this a stress-free adventure filled with nature\u2019s wonders.",
