            "description": "Take part in an exciting 3-day journey to explore two of Indonesia's most renowned destinations: <span class=\"fw-600\">Taman Safari Prigen and Mount Bromo</span>.\r\nThis adventure is perfect for explorers who love nature and want to witness breathtaking landscapes. The tour begins with a visit to <span class=\"fw-600\">Taman Safari Prigen</span>, where you'll enjoy a variety of wildlife encounters and experience an immersive animal safari. Next, we head to <span class=\"fw-600\">Mount Bromo</span> to witness the stunning sunrise illuminating the vast caldera and surrounding peaks. The journey continues to the hidden gem of <span class=\"fw-600\">Madakaripura Waterfall</span>, nestled within lush green cliffs, offering a refreshing and serene experience.\r\n<br>\r\n<br>\r\nThroughout the tour, you'll enjoy <span class=\"fw-600\">comfortable accommodations, private transportation</span>, and the guidance of experienced <span class=\"fw-600\">English-speaking guides</span>. This expedition is designed to provide a seamless and enriching exploration of Java's natural wonders, ensuring an unforgettable experience for all participants.",
